export const state={renderToken:0,activeTimeouts:new Set,activeAnimationFrames:new Set,profileAsciiFrames:[],activityMessages:[],isPageVisible:!document.hidden,printAtsReport:null,resizePrintTimeoutId:null,launcherTerminalText:"",launcherSpeechText:""};export function trackTimeout(e,t){const i=window.setTimeout(function(){state.activeTimeouts.delete(i),e()},t);return state.activeTimeouts.add(i),i}export function clearActiveTimeouts(){state.activeTimeouts.forEach(function(e){window.clearTimeout(e)}),state.activeTimeouts.clear()}export function trackAnimationFrame(e){const t=window.requestAnimationFrame(function(i){state.activeAnimationFrames.delete(t),e(i)});return state.activeAnimationFrames.add(t),t}export function clearActiveAnimationFrames(){state.activeAnimationFrames.forEach(function(e){window.cancelAnimationFrame(e)}),state.activeAnimationFrames.clear()}export function clearActiveAsyncWork(){clearActiveTimeouts(),clearActiveAnimationFrames()}